@property
def num_blocks(self):                                                  # (1)
    return (self.num_tokens + self.block_size - 1) // self.block_size  # 向上取整除法，如 300 tokens / 256 = 2 blocks

def block(self, i):                                                    # (2)
    assert 0 <= i < self.num_blocks
    return self.token_ids[i*self.block_size: (i+1)*self.block_size]   # 按 block_size 切片，用于哈希计算和前缀匹配

@property
def last_block_num_tokens(self):                                       # (3)
    return self.num_tokens - (self.num_blocks - 1) * self.block_size   # 最后一个块的实际 token 数（≤ block_size）

@property
def is_finished(self):
    return self.status == SequenceStatus.FINISHED    # (1) 状态查询快捷方式，供 generate() 检测

@property
def num_completion_tokens(self):
    return self.num_tokens - self.num_prompt_tokens  # (2) 已生成的 token 数 = 总 token - prompt

@property
def prompt_token_ids(self):
    return self.token_ids[:self.num_prompt_tokens]   # (3) 仅返回 prompt token，按切片提取

@property
def completion_token_ids(self):
    return self.token_ids[self.num_prompt_tokens:]   # (4) 仅返回生成 token，供 generate() 拼接输出

def __len__(self):
    return self.num_tokens                     # (1) len(seq) 返回总 token 数

def __getitem__(self, key):
    return self.token_ids[key]                 # (2) seq[i] 等价于 seq.token_ids[i]，支持切片
